const card = 'background:#fff;border:1px solid #e4e4e0;border-radius:12px;';
const mbtn = (kind, disabled, small) => btn(kind, disabled, small ? 's' : '').replace('height:32px;padding:0 12px;font-size:12.5px;', 'height:44px;padding:0 16px;font-size:14px;border-radius:10px;justify-content:center;') + (small ? '' : 'width:100%;');
const act = (label, kind, onClick, perm, small) => { const ok = !perm || perm.ok; return { label, onClick: ok ? onClick : () => {}, disabled: !ok, reason: ok ? '' : perm.reason, style: mbtn(kind, !ok, small) }; };
const stPill = (s) => ({ bg: STATUS[s].bg, fg: STATUS[s].fg });

